@reference "../../styles.css";

:host {
  @apply grid min-w-0 gap-6;
}

.hero-detail__back {
  @apply justify-self-start;
}

.hero-detail__header {
  @apply flex min-w-0 flex-wrap items-start justify-between gap-4;
}

.hero-detail__identity {
  @apply flex min-w-0 flex-1 items-center gap-4;
}

.hero-detail__avatar {
  @apply shrink-0;
}

.hero-detail__names {
  @apply flex min-w-0 flex-col gap-1;
}

.hero-detail__id {
  @apply text-xs font-medium text-muted-foreground tabular-nums;
}

.hero-detail__title {
  @apply text-2xl font-semibold tracking-tight break-words;
}

.hero-detail__alias {
  @apply text-sm text-muted-foreground;
}

.hero-detail__badges {
  @apply flex flex-wrap items-center gap-2 pt-1;
}

.hero-detail__status::before {
  @apply size-2 rounded-full bg-muted-foreground;
  content: '';
}

.hero-detail__status--active::before {
  background: var(--success);
}

.hero-detail__status--injured::before {
  background: var(--warning);
}

.hero-detail__status--mia::before {
  background: var(--destructive);
}

.hero-detail__actions {
  @apply flex flex-wrap items-center gap-2;
}

.hero-detail__dialog-footer {
  @apply flex flex-wrap justify-end gap-2;
}

.hero-detail__notice {
  @apply min-h-5 text-sm text-muted-foreground;
}

.hero-detail__tabs {
  @apply grid min-w-0 gap-4;
}

.hero-detail__tab-list {
  @apply max-w-full overflow-x-auto;
}

.hero-detail__panel {
  @apply min-w-0;
}

.hero-detail__stats {
  @apply grid grid-cols-1 gap-4 sm:grid-cols-3;
}

.hero-detail__dossier,
.hero-detail__meters,
.hero-detail__abilities,
.hero-detail__missions {
  @apply grid min-w-0 gap-3 rounded-lg border border-border bg-card p-4 text-card-foreground shadow-sm;
}

.hero-detail__powers {
  @apply grid grid-cols-1 gap-4 md:grid-cols-2;
}

.hero-detail__section-title {
  @apply text-base font-semibold;
}

.hero-detail__facts,
.hero-detail__results {
  @apply grid grid-cols-1 gap-3 sm:grid-cols-2;
}

.hero-detail__fact--wide {
  @apply sm:col-span-2;
}

.hero-detail__fact,
